prompt --application/shared_components/navigation/lists/dynamic_menu
begin
wwv_flow_api.create_list(
 p_id=>wwv_flow_api.id(5382046366597511)
,p_name=>'dynamic menu'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT LEVEL,',
'                  MENU_NAME label,',
'                  DECODE (',
'                     MENU_LINK,',
'                     NULL, '''',',
'                     DECODE (',
'                        CONNECT_BY_ISLEAF,',
'                        0, '''',',
'                        ''f?p=&APP_ID.:'' || TO_CHAR (MENU_LINK) || '':&SESSION.:::::''))',
'                     target,',
'                  ''NO:'' AS is_current,',
'                  NVL (icon_img, ''fa-list-ul'') image,',
'                  PARENT_PID',
'             FROM t_MENU',
'            WHERE     status = 1',
'                  AND pid IN (SELECT PAGE_ID',
'                                FROM user_menu',
'                               WHERE PID_GROUP = :G_USER_GRP)',
'       START WITH PARENT_PID IS NULL',
'       CONNECT BY PRIOR pid = PARENT_PID',
'ORDER SIBLINGS BY SORT_BY;'))
,p_list_status=>'PUBLIC'
);
end;
/
