'    l_user_id NUMBER;',
'BEGIN',
'    -- Get the currently logged-in user ID',
'    l_user_id := :user_id;',
'',
'    IF :P3_ID IS NOT NULL THEN',
'        -- Update',
'        UPDATE DESIGNATIONS',
'        SET upd_by = l_user_id,',
'            upd_date = sysdate',
'        WHERE id = :P3_ID;',
'    END IF;',
' exception ',
