,p_display_point=>'REGION_POSITION_02'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT "ID",',
'    NULL link_class,',
'    apex_page.get_url (p_items => ''P14_ID'', p_values => "ID") link,',
'    NULL icon_class,',
'    NULL link_attr,',
'    NULL icon_color_class,',
'    CASE',
'        WHEN NVL (:P14_ID, ''0'') = "ID" THEN ''is-active''',
'        ELSE '' ''',
'    END list_class,',
'    SUBSTR ("EMP_ID", 1, 50) || (',
'        CASE',
'            WHEN LENGTH ("EMP_ID") > 50 THEN ''...''',
'        END',
'    ) list_title,',
'    SUBSTR ("F_NAME" || '' '' || "L_NAME", 1, 50) || (',
'        CASE',
'            WHEN LENGTH ("F_NAME" || '' '' || "L_NAME") > 50 THEN ''...''',
'        END',
'    ) list_text,',
'    NULL list_badge',
'FROM "EMPLOYEES" x',
'WHERE (',
'        :P14_SEARCH IS NULL',
'        OR UPPER (x."EMP_ID") LIKE ''%'' || UPPER (:P14_SEARCH) || ''%''',
'        OR UPPER ((x."F_NAME" || '' '' || x."L_NAME")) LIKE ''%'' || UPPER (:P14_SEARCH) || ''%''',
'    )',
'ORDER BY "EMP_ID"'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P14_SEARCH'
,p_lazy_loading=>true
,p_query_row_template=>wwv_flow_api.id(5156415172024351)
,p_query_num_rows=>30
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'<div class="u-tC">No data found.</div>'
