wwv_flow_api.create_report_region(
 p_id=>wwv_flow_api.id(7842599460498722)
,p_name=>'Basic Information'
,p_template=>wwv_flow_api.id(5133259516024345)
,p_display_sequence=>10
,p_region_css_classes=>'js-master-region'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-AVPList--leftAligned'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT es.id,',
'       es.emp_id,',
'       es.f_name || '' '' || es.l_name    fname,',
'       es.dob,',
'       es.mobile,',
'       dp.DEPT_NAME,',
'       dg.DESIGNATION,',
'       es.email,',
'       es.father,',
'       es.mother,',
'       es.gender,',
'       es.height,',
'       es.weight                        AS weight,',
'       es.blood,',
'       es.nid,',
'          ''Area/Village: ''',
'       || es.address',
'       || '', Post Office: ''',
'       || NVL (un.name, ''N/A'')',
'       || '', Thana/Upazila: ''',
'       || NVL (upz.name, ''N/A'')',
'       || '', District: ''',
'       || NVL (dis.name, ''N/A'')',
'       || '', Division: ''',
'       || NVL (div.name, ''N/A'')         AS address,',
'       es.c_post,',
'       es.c_thana,',
'       es.c_district,',
'       es.c_division,',
'          ''Area/Village: ''',
'       || es.p_address',
'       || '', Post Office: ''',
'       || NVL (un1.name, ''N/A'')',
'       || '', Thana/Upazila: ''',
'       || NVL (upz1.name, ''N/A'')',
'       || '', District: ''',
'       || NVL (dis1.name, ''N/A'')',
'       || '', Division: ''',
'       || NVL (div1.name, ''N/A'')        AS p_address,',
'       es.p_post,',
'       es.p_thana,',
'       es.p_district,',
'       es.p_division,',
'       DBMS_LOB.getlength (es.photo)    photo,',
'       es.join_date,',
'       es.marital_status,',
'       es.emp_type,',
'       es.dept_id,',
'       es.loc_id,',
'       es.branch_id,',
'       es.desig_id,',
'       es.com_id,',
'       es.job_id,',
'       es.user_grp,',
'       es.passw,',
'       es.ent_by,',
'       es.ent_date,',
'       es.upd_by,',
'       es.upd_date,',
'       es.status',
'  FROM employees     es,',
'       division      div,',
'       district      dis,',
'       upazila       upz,',
'       unions        un,',
'       division      div1,',
'       district      dis1,',
'       upazila       upz1,',
'       unions        un1,',
'       departments   dp,',
'       designations  dg',
' WHERE     es.c_post = un.id(+)',
'       AND es.c_thana = upz.id(+)',
'       AND es.c_district = dis.id(+)',
'       AND es.c_division = div.id(+)',
'       AND es.p_post = un1.id(+)',
'       AND es.p_thana = upz1.id(+)',
'       AND es.p_district = dis1.id(+)',
'       AND es.p_division = div1.id(+)',
'       AND es.dept_id = dp.id(+)',
'       AND es.desig_id = dg.id(+)',
'       AND es.id = :P14_ID',
'-- select ID,',
'--        EMP_ID,',
'--        F_NAME || '' ''||',
'--        L_NAME Fname,',
'--        DOB,',
'--        MOBILE,',
'--        EMAIL,',
'--        FATHER,',
'--        MOTHER,',
'--        GENDER,',
'--        HEIGHT,',
'--        WEIGHT ||'' kg'' as WEIGHT,',
'--        BLOOD,',
'--        NID,',
'--        ADDRESS,',
'--        C_POST,',
'--        C_THANA,',
'--        C_DISTRICT,',
'--        C_DIVISION,',
'--        P_ADDRESS,',
'--        P_POST,',
'--        P_THANA,',
'--        P_DISTRICT,',
'--        P_DIVISION,',
'--        PHOTO,',
'--        JOIN_DATE,',
'--        MARITAL_STATUS,',
'--        EMP_TYPE,',
'--        DEPT_ID,',
'--        LOC_ID,',
'--        BRANCH_ID,',
'--        DESIG_ID,',
'--        COM_ID,',
'--        JOB_ID,',
'--        USER_GRP,',
'--        PASSW,',
'--        ENT_BY,',
'--        ENT_DATE,',
'--        UPD_BY,',
'--        UPD_DATE,',
'--        STATUS',
'--   from EMPLOYEES',
'--  where "ID" = :P14_ID'))
,p_display_when_condition=>'P14_ID'
,p_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_api.id(5161879027024352)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No Record Selected'
,p_query_row_count_max=>500
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'Y'
);
