wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(9193112150113445)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Employee code Generate'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_emp_id         NUMBER (10);    ',
'    v_code              VARCHAR2(30);',
'BEGIN',
'    SELECT code',
'      INTO v_code',
'      FROM company',
'     WHERE id = :g_com_id;',
'',
'    SELECT NVL (MAX (id), 0) + 1',
'      INTO  v_emp_id',
'      FROM employees ;',
'',
'    :P15_EMP_ID := v_code || ''-'' || LTRIM (TO_CHAR ( v_emp_id, ''000000''));',
'      ',
'-- :GOODS_REC_M.grn_no :=lpad(rtrim(ltrim(to_char(nREC_BATCH_ID))),5,''0'');',
'EXCEPTION',
'    WHEN NO_DATA_FOUND',
'    THEN',
'        :P15_EMP_ID := ''INM'' || ''-'' || ''000001'';',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(7832697746498706)
,p_process_when=>'P15_EMP_ID'
,p_process_when_type=>'ITEM_IS_NULL'
);
