'    l_user_id NUMBER;',
'BEGIN',
'    -- Get the currently logged-in user ID',
'    l_user_id := :user_id;',
'',
'    IF :P18_ID IS NOT NULL THEN',
'        -- Update',
'        UPDATE EMP_EDUCATION',
'        SET upd_by = l_user_id,',
'            upd_date = sysdate',
'        WHERE id = :P18_ID;',
'    END IF;',
' exception ',
'    when others then ',
'    null;',
'END;',
''))
