,p_attribute_01=>'SQL_STATEMENT'
,p_attribute_03=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CASE',
'           WHEN STR_TYPE = ''DEPT'' AND PARENT_ID <> 0 THEN ''SECTION''',
'           WHEN STR_TYPE = ''LOC'' AND PARENT_ID <> 0 THEN ''DEPO''',
'           WHEN STR_TYPE = ''FLD'' THEN ''REGION''',
'           WHEN STR_TYPE = ''REGION'' AND PARENT_ID <> 0 THEN ''ZONE''',
'           WHEN STR_TYPE = ''ZONE'' AND PARENT_ID <> 0 THEN ''AREA''',
'           WHEN STR_TYPE = ''AREA'' AND PARENT_ID <> 0 THEN ''TERI''',
'           ELSE STR_TYPE',
'       END    AS d,',
'       ID     r',
'  FROM T_STRUCTURE',
' WHERE id = :P34_PARENT_ID'))
