wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(5312205839519901)
,p_validation_name=>'Password Validate'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'V_PASS VARCHAR2(100);',
'BEGIN',
'SELECT passw',
'INTO V_PASS',
'  FROM employees',
' WHERE     upper(emp_id) = upper(:P9999_USERNAME)     ',
'       AND STATUS = 1;',
'IF V_PASS = :P9999_PASSWORD THEN',
'RETURN TRUE;',
'ELSE ',
'RETURN FALSE;',
'END IF;',
'exception ',
'when no_data_found',
'then  ',
'return false;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Username or Password Incorrect !!!'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
