 p_id=>wwv_flow_api.id(5239966653024401)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Username Cookie'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex_authentication.send_login_username_cookie (',
'    p_username => lower(:P9999_USERNAME),',
'    p_consent  => :P9999_REMEMBER = ''Y'' );'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5239520129024401)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Login'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex_authentication.login(',
'    p_username => :P9999_USERNAME,',
'    p_password => :P9999_PASSWORD );',
'DECLARE',
'    V_CHK       NUMBER;',
'    V_SESSION   NUMBER;',
'    V_SID       NUMBER;',
'    V_SERIAL    NUMBER;',
'    V_LOGIN     NUMBER;',
'    V_MACHINE   VARCHAR2 (100);',
'    V_RPT_URL   VARCHAR2 (100);',
'    V_DIR       VARCHAR2 (100);',
'    v_com       NUMBER;',
'BEGIN',
'    SELECT COUNT (*)',
'      INTO V_CHK',
'      FROM employees',
'     WHERE lower(emp_id) = lower( :P9999_USERNAME) AND status = 1;',
'',
'    BEGIN',
'        SELECT emp_id,',
'               USER_GRP,',
'               com_id,',
'               com_id,',
'               id',
'          INTO :g_uname,',
'               :g_user_grp,',
'               :G_COM_ID,',
'               v_com,',
'               :user_id',
'          FROM employees',
'         WHERE lower (emp_id) = lower ( :P9999_USERNAME);',
'',
'       SELECT CODE INTO :G_COM_CODE',
'       FROM COMPANY',
'       WHERE ID = v_com;',
'',
'    EXCEPTION',
'        WHEN OTHERS',
'        THEN',
'            :G_COM_ID := 1;',
'            :G_COM_CODE	:= ''INM'';',
'            :user_id := 1;',
'    END;',
'-- EXCEPTION',
'--  WHEN OTHERS THEN NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5240710490024401)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_SESSION_STATE'
,p_process_name=>'Clear Page(s) Cache'
,p_attribute_01=>'CLEAR_CACHE_CURRENT_PAGE'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(5240389881024401)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get Username Cookie'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P9999_USERNAME := apex_authentication.get_login_username_cookie;',
':P9999_REMEMBER := case when :P9999_USERNAME is not null then ''Y'' end;'))
,p_process_clob_language=>'PLSQL'
);
end;
